import http from 'http';
import assert from 'assert';
import formidable from '/data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-bd61twvw/testbed/node_modules/formidable/src/index.js';
import axios from '/data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-bd61twvw/testbed/index.js';
import FormDataLegacy from '/data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-bd61twvw/testbed/node_modules/form-data/lib/form_data.js';

const handleFormData = (req) => new Promise((resolve, reject) => {
  const form = new formidable.IncomingForm();
  form.parse(req, (err, fields, files) => err ? reject(err) : resolve({fields, files}));
});

const server = http.createServer(async (req, res) => {
  if (req.url === '/echo') {
    const chunks = [];
    for await (const chunk of req) chunks.push(chunk);
    res.end(Buffer.concat(chunks));
    return;
  }
  const {fields, files} = await handleFormData(req);
  res.end(JSON.stringify({fields, files}));
});

await new Promise(resolve => server.listen(0, resolve));
const url = `http://localhost:${server.address().port}`;

try {
  const form = new FormData();
  form.append('foo1', 'bar1');
  form.append('foo2', 'bar2');
  form.append('file1', new Blob(['blob-content'], {type: 'image/jpeg'}));
  const {data} = await axios.post(url, form, {maxRedirects: 0});
  assert.deepStrictEqual(data.fields, {foo1: 'bar1', foo2: 'bar2'});
  assert.deepStrictEqual(
    {size: data.files.file1.size, mimetype: data.files.file1.mimetype, originalFilename: data.files.file1.originalFilename},
    {mimetype: 'image/jpeg', originalFilename: 'blob', size: 12}
  );
  console.log('spec FormData OK');

  const blobContent = 'blob-content';
  const blobRes = await axios.post(url + '/echo', new Blob([blobContent], {type: 'image/jpeg'}), {maxRedirects: 0});
  assert.strictEqual(blobRes.data, blobContent);
  console.log('Blob OK');

  const legacy = new FormDataLegacy();
  legacy.append('foo', 'bar');
  legacy.append('file1', Buffer.from('foo'), {filename: 'bar.jpg', contentType: 'image/jpeg'});
  const legacyRes = await axios.post(url, legacy, {headers: {'Content-Type': 'multipart/form-data'}});
  assert.deepStrictEqual(legacyRes.data.fields, {foo: 'bar'});
  assert.strictEqual(legacyRes.data.files.file1.mimetype, 'image/jpeg');
  assert.strictEqual(legacyRes.data.files.file1.size, 3);
  console.log('legacy form-data OK');
} finally {
  server.close();
}

